  margin-top: calc(var(--cipher-space-field-label) - var(--cipher-space-field-legend));
}
[data-slot="field-set"]:has(> .fieldLegend[data-variant="legend"]) {
  row-gap: var(--cipher-space-field-legend);
}
.fieldGroup > [data-slot="field-set"]:has(> .fieldLegend[data-variant="legend"]) + *,
.fieldGroup > * + [data-slot="field-set"]:has(> .fieldLegend[data-variant="legend"]) {
  margin-top: calc(var(--cipher-space-content-section) - var(--cipher-space-field-group));
}
.fieldLegend[data-variant="label"] {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.alertTitle {
  grid-column: 1;
  grid-row: 1;
  min-width: 0;
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
}
.alertDescription {
  grid-column: 1;
  min-width: 0;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}

:is(.fieldDescription, .alertDescription) a:not([data-slot]) {
  color: var(--cipher-link);
  text-decoration-line: none;
  text-decoration-thickness: var(--cipher-size-control-border);
  text-underline-offset: var(--cipher-space-3);
}
:is(.fieldDescription, .alertDescription) a:not([data-slot]):focus-visible {
  text-decoration-line: underline;
}
@media (hover: hover) {
  :is(.fieldDescription, .alertDescription) a:not([data-slot]):hover {
    color: var(--cipher-text2);
    text-decoration-line: underline;
    text-decoration-thickness: var(--cipher-space-2);
  }
}

.alert {
  position: relative;
  display: grid;
  width: 100%;
  grid-template-columns: minmax(0, 1fr);
  border: 1px solid var(--cipher-line-soft);
  border-radius: 0;
  padding: var(--cipher-space-12);
  gap: var(--cipher-space-4) var(--cipher-space-8);
  overflow-wrap: anywhere;
  text-align: start;
}
.alert[data-has-icon] {
  grid-template-columns: auto minmax(0, 1fr);
}
.alert > svg {
  --cipher-lead-line: var(--cipher-type-row-title-line-height);
  grid-column: 1;
  grid-row: 1 / span 2;
  color: currentColor;
}
.alert[data-has-icon]:not([data-has-title]) > svg {
  --cipher-lead-line: var(--cipher-type-small-line-height);
  --cipher-lead-size: var(--cipher-size-icon-small);
  grid-row: 1;
  width: var(--cipher-size-icon-small);
  height: var(--cipher-size-icon-small);
}
.alert[data-has-icon] > :is(.alertTitle, .alertDescription) {
  grid-column: 2;
}
.alert[data-has-title] > .alertDescription {
  grid-row: 2;
}
.alert[data-has-action] {
  grid-template-columns: minmax(0, 1fr) auto;
  padding-inline-end: var(--cipher-space-12);
}
.alert[data-has-icon][data-has-action] {
  grid-template-columns: auto minmax(0, 1fr) auto;
}
.alert[data-has-icon] > .alertTitleRow {
  grid-column: 2;
}
.alertTitleRow {
  grid-row: 1;
  --cipher-title-badges-line: var(--cipher-type-row-title-line-height);
}
.alertLine {
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-8);
}
.alertLine > :first-child {
  flex: 1;
  min-width: 0;
}
.alertTrailing {
  display: inline-flex;
  flex: 0 1 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  max-width: 50%;
  align-items: center;
  gap: var(--cipher-space-6);
  min-height: var(--cipher-type-small-line-height);
}
.titleWithBadges {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: var(--cipher-space-4) var(--cipher-space-8);
  min-width: 0;
}
.titleWithBadges > :first-child {
  flex: 0 1 auto;
  min-width: 0;
}
.titleBadges {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--cipher-space-6);
  min-width: 0;
  max-width: 100%;
  min-height: var(--cipher-title-badges-line, auto);
}
:is(.titleBadges, .alertTrailing) > :not([data-slot="documentation-link"]) {
  max-width: 100%;
}
.alertAction {
  position: static;
  grid-column: -2 / -1;
  grid-row: 1 / span 2;
  align-self: start;
}

.fieldTitle {
  font-family: var(--cipher-type-field-label-font-family);
  font-size: var(--cipher-type-field-label-font-size);
  line-height: var(--cipher-type-field-label-line-height);
  font-weight: var(--cipher-type-field-label-font-weight);
  letter-spacing: var(--cipher-type-field-label-letter-spacing);
}
.fieldGroup {
  gap: var(--cipher-space-field-group);
}
.field {
  gap: var(--cipher-space-field-label);
}
.field:not([data-orientation="horizontal"]),
.field[data-orientation="horizontal"]:not([data-width="wide"]):is(
    :global([data-slot="field"]:not([data-orientation="horizontal"])) ~ *,
    :has(~ :global([data-slot="field"]:not([data-orientation="horizontal"])))
  ) {
  max-width: var(--cipher-size-measure-field);
}
.field[data-width="wide"] {
  max-width: var(--cipher-size-measure-field-wide);
}
.field[data-orientation="horizontal"] {
  gap: var(--cipher-space-12);
}

.lede {
  margin: 0;
  color: var(--cipher-text2);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.form {
  min-width: 0;
}
/* The steps slide inside this clip, so it reaches --cipher-focus-clearance past the content on every
   side and gives it back as negative margin: rings at the content edge are drawn, alignment holds. */
.viewport {
  position: relative;
  box-sizing: content-box;
  flex: 1 1 auto;
  min-width: 0;
  overflow: clip;
  padding: var(--cipher-focus-clearance);
  margin: calc(-1 * var(--cipher-focus-clearance));
}
.body {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-field-group);
  min-width: 0;
}
.footer.footer {
  display: flex;
  flex-direction: row;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--cipher-space-12);
}
.start {
  display: flex;
  flex: none;
  align-items: center;
  gap: var(--cipher-space-8);
  max-width: 100%;
}
.status {
  min-width: 0;
  margin: 0;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.error {
  color: var(--cipher-bad);
}
.buttons {
  display: flex;
  flex: 0 1 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  min-width: 0;
  gap: var(--cipher-space-12);
  margin-inline-start: auto;
}
.buttons > * {
  max-width: 100%;
}
.page {
  container-type: inline-size;
  min-width: 0;
}
.pageGrid {
  display: grid;
  grid-template-columns: 220px minmax(0, 1fr);
  gap: var(--cipher-space-32);
  align-items: start;
  min-width: 0;
}
.pageGrid[data-single] {
  grid-template-columns: minmax(0, 1fr);
}
.bar {
  display: none;
}
.card {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-20);
  min-width: 0;
  padding: var(--cipher-space-surface-inset);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: 0;
  background: var(--cipher-surface);
}
@container (max-width: 640px) {
  .pageGrid {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--cipher-space-16);
  }
  .rail {
    display: none;
  }
  .bar {
    display: block;
  }
}
.stepHead {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-4);
  margin-bottom: var(--cipher-space-8);
}
.eyebrow {
  margin: 0;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-eyebrow-font-family);
  font-size: var(--cipher-type-eyebrow-font-size);
  line-height: var(--cipher-type-eyebrow-line-height);
  font-weight: var(--cipher-type-eyebrow-font-weight);
  letter-spacing: var(--cipher-type-eyebrow-letter-spacing);
  text-transform: uppercase;
}
.headingRow {
  --cipher-title-badges-line: var(--cipher-type-title-line-height);
}
.heading {
  margin: 0;
  font-family: var(--cipher-type-title-font-family);
  font-size: var(--cipher-type-title-font-size);
  line-height: var(--cipher-type-title-line-height);
  font-weight: var(--cipher-type-title-font-weight);
  letter-spacing: var(--cipher-type-title-letter-spacing);
}
.steps {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}
.step {
  position: relative;
  padding-bottom: var(--cipher-space-20);
}
.step:not(:last-child)::before {
  content: "";
  position: absolute;
  top: var(--cipher-space-24);
  bottom: 0;
  left: 11px;
  width: 1px;
  background: var(--cipher-line-soft);
}
.step[data-state="done"]::before {
  background: var(--cipher-ink);
}
.stepButton {
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-12);
  width: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  text-align: start;
}
button.stepButton:focus-visible {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: var(--cipher-size-focus-ring);
}
.marker {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: var(--cipher-space-24);
  height: var(--cipher-space-24);
  border: 1px solid var(--cipher-line-soft);
  border-radius: 0;
  background: var(--cipher-surface);
  color: var(--cipher-muted);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  font-variant-numeric: tabular-nums;
}
.step[data-state="current"] .marker {
  border-color: var(--cipher-ink);
  color: var(--cipher-ink);
}
.step[data-state="done"] .marker {
  border-color: var(--cipher-ink);
  background: var(--cipher-ink);
  color: var(--cipher-on-ink);
}
.stepText {
  display: flex;
  flex-direction: column;
  min-width: 0;
  padding-top: 2px;
}
.stepTitle {
  color: var(--cipher-text2);
  font-family: var(--cipher-type-label-font-family);
  font-size: var(--cipher-type-label-font-size);
  line-height: var(--cipher-type-label-line-height);
  font-weight: var(--cipher-type-label-font-weight);
}
.step[data-state="current"] .stepTitle {
  color: var(--cipher-ink);
  font-weight: 600;
}
.stepSummary {
  overflow: hidden;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.fields {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
.asideFrame {
  container-type: inline-size;
}
.asideDialog.asideDialog {
  max-width: var(--cipher-size-sheet-xl);
}
.asideGrid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--cipher-space-overlay-inset);
  min-width: 0;
}
.asideGrid[data-rail] {
  grid-template-columns: var(--cipher-size-tile-min) minmax(0, 1fr);
}
.asideGrid[data-aside] {
  grid-template-columns: minmax(0, 1fr) var(--cipher-size-popover);
}
.asideGrid[data-rail][data-aside] {
  grid-template-columns: var(--cipher-size-tile-min) minmax(0, 1fr) var(--cipher-size-popover);
}
.asideGrid > .rail {
  min-width: 0;
  padding-inline-end: var(--cipher-space-overlay-inset);
  border-inline-end: var(--cipher-size-control-border) solid var(--cipher-line-soft);
}
.asideGrid > .form {
  align-self: start;
}
.aside {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-12);
  min-width: 0;
  padding-inline-start: var(--cipher-space-overlay-inset);
  border-inline-start: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  overflow-wrap: anywhere;
}
.about {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-12);
  overflow-wrap: anywhere;
}
.docs {
  display: inline-flex;
  align-items: center;
  gap: var(--cipher-space-4);
  align-self: flex-start;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
}
.headRow {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--cipher-space-12);
  min-width: 0;
}
.headRow > .heading {
  min-width: 0;
}
.aboutToggle.aboutToggle {
  display: none;
  flex: none;
  margin-inline-start: auto;
}
@container (width < 960px) {
  .asideGrid[data-aside] {
    grid-template-columns: minmax(0, 1fr);
  }
  .asideGrid[data-rail][data-aside] {
    grid-template-columns: var(--cipher-size-tile-min) minmax(0, 1fr);
  }
  .aside {
    display: none;
  }
  .aboutToggle.aboutToggle {
    display: inline-flex;
  }
}
@container (width <= 640px) {
  .asideGrid[data-rail],
  .asideGrid[data-rail][data-aside] {
    grid-template-columns: minmax(0, 1fr);
  }
}
@container (width > 640px) {
  .meter.meter {
    display: none;
  }
}
.titleRow {
  display: flex;
  gap: inherit;
  column-gap: var(--cipher-space-12);
  min-width: 0;
}
.media {
  --cipher-lead-row: var(--cipher-type-title-line-height);
}
.titleText {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: inherit;
  min-width: 0;
}
